INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2915203', 'Ethiopian–Adal War', 'The Ethiopian–Adal War, also known as the Abyssinian–Adal War and Futūḥ Al-Ḥabaša (Arabic: فتوح الحبش, lit. ''Conquest of Abyssinia''), was a war fought between the Christian Ethiopian Empire and the Muslim Adal Sultanate from 1529 to 1543. The Christian Ethiopian troops were drawn mainly from Tigray, Amhara, Gojjam, Begemder, Angot, Qeda, Gan, Medri Bahri, Gafat, and a certain numbers of Agaw troops At the closing of the war, the Christian forces were supported by the Portuguese Empire with no less than 400 musketeers.', 1529, NULL, NULL, 1543, NULL, NULL, 'year', '1529–1543', 55, 'https://en.wikipedia.org/wiki/Ethiopian%E2%80%93Adal_War'),
  ('Q834881', 'Battle of Jarte', 'The Battle of Jarte was fought from 4 to 16 April 1542 between the forces of Ahmad ibn Ibrahim al-Ghazi and the Ethiopian Empire assisted by a Portuguese expeditionary force led by Cristóvão da Gama. The Abyssinians and Portuguese were victorious, with Ahmad ibn Ibrahim al-Ghazi wounded by the outnumbered Christian force, and the Adalites forced to retreat.', 1542, 4, 4, 1542, 4, 16, 'day', '4 April 1542 – 16 April 1542', 34, 'https://en.wikipedia.org/wiki/Battle_of_Jarte'),
  ('Q947667', 'Battle of Magdala', 'The Battle of Magdala was the conclusion of the British Expedition to Abyssinia fought in April 1868 between British and Abyssinian forces at Magdala, 390 miles (630 km) from the Red Sea coast. The British were led by Robert Napier, while the Abyssinians were led by Emperor Tewodros II. The Battle of Derasge marked a decisive turning point in Ethiopian history, bringing an end to the Zemene Mesafint (''Era of the Princes'') and paving the way for the rise of Emperor Tewodros II and the unification of the Ethiopian Empire.', 1868, 4, 9, 1868, 4, 13, 'day', '9 April 1868 – 13 April 1868', 41, 'https://en.wikipedia.org/wiki/Battle_of_Magdala'),
  ('Q2887945', 'Battle of Embabo', 'The Battle of Embabo was fought 6 June 1882, between the Shewan forces of Negus Menelik and the Gojjame forces of Negus Tekle Haymanot. The forces fought to gain control over Wallaga and Kaffa provinces south of the Blue Nile (Abay).', 1882, 6, 6, NULL, NULL, NULL, 'day', '6 June 1882', 34, 'https://en.wikipedia.org/wiki/Battle_of_Embabo'),
  ('Q1398069', 'Battle of Amba Alagi', 'The Battle of Amba Alagi was the first in a series of battles between the Italian General Baratieri and Ethiopia''s Emperor Menelik during the First Italo-Ethiopian War. Amba Alagi was one of Baratieri''s forward positions; it was under the command of Major Toselli with 2,000 Eritrean Askari.', 1895, 12, 7, NULL, NULL, NULL, 'day', '7 December 1895', 55, 'https://en.wikipedia.org/wiki/Battle_of_Amba_Alagi_(1895)'),
  ('Q302519', 'Battle of Adwa', 'The Battle of Adwa was the climactic battle of the First Italo-Ethiopian War. It was fought on 1 March 1896, near the town of Adwa between the Ethiopian Empire under Emperor Menelik II and an Italian colonial force led by General Oreste Baratieri.', 1896, 3, 1, NULL, NULL, NULL, 'day', '1 March 1896', 72, 'https://en.wikipedia.org/wiki/Battle_of_Adwa'),
  ('Q2237609', 'Battle of Mek''ele', 'The siege of Mekelle, sometimes known as the battle of Mekelle, took place in January 1896 during the First Italo-Ethiopian War. Italian forces surrendered a partially completed fort at Mekelle, a city in the northern Tigray Region of Ethiopia which they had occupied since 1895, to Ethiopian forces.', 1896, 1, NULL, 1896, 1, 21, 'month', 'January 1896 – 21 January 1896', 43, 'https://en.wikipedia.org/wiki/Siege_of_Mekelle'),
  ('Q2399119', 'Treaty of Addis Ababa', 'The Treaty of Addis Ababa, signed on 26 October 1896, formally ended the First Italo-Ethiopian War on terms mostly favourable to Ethiopia. This treaty superseded a secret agreement between Ethiopia and Italy negotiated days after the decisive Battle of Adwa in March of the same year, in which Ethiopian forces commanded by Menelik II defeated the Italians.', 1896, 10, 26, NULL, NULL, NULL, 'day', '26 October 1896', 53, 'https://en.wikipedia.org/wiki/Treaty_of_Addis_Ababa'),
  ('Q1567243', 'Anglo-Ethiopian Treaty of 1897', 'The Anglo-Ethiopian Treaty of 1897 (sometimes called the Rodd Treaty) was an agreement signed between the British and Ethiopian Empire, negotiated between diplomat Sir Rennell Rodd and Emperor Menelik II of Ethiopia. The treaty primarily focused on border issues between the two empires in Somali inhabited regions that they had expanded into over the previous decade.', 1897, 5, 14, NULL, NULL, NULL, 'day', '14 May 1897', 41, 'https://en.wikipedia.org/wiki/Anglo-Ethiopian_Treaty_of_1897'),
  ('Q5403603', 'Ethiopian coup d''état of 1928', 'The 1928 Ethiopian coup d''état attempt was orchestrated by supporters of Empress Zewditu to rid her of the heir apparent and Crown Prince, Ras Tafari Makonnen. With Tafari gone, Zewditu would be the sole ruler of the Ethiopian Empire (Mangista Ityop''p''ya).', 1928, 9, NULL, NULL, NULL, NULL, 'month', 'September 1928', 30, 'https://en.wikipedia.org/wiki/1928_Ethiopian_coup_attempt'),
  ('Q3149889', 'Ual-Ual Incident', 'The Ual-Ual Incident or Walwal Incident (in Italian: Incidente di Ual Ual; in Somali: Dhacdadii Walwaal; in Amharic: የወልወል ክስተት) was an armed conflict in which Ethiopian troops attacked the Italian garrison in Ual-Ual. On 5 December 1934, after a few weeks of tension between the garrison and Ethiopian armed men, a violent firefight began for the possession of the locality, which was located in a strip of disputed territory.', 1934, 12, 5, NULL, NULL, NULL, 'day', '5 December 1934', 34, 'https://en.wikipedia.org/wiki/Ual-Ual_Incident'),
  ('Q2887840', 'Battle of Amba Aradam', 'The Battle of Amba Aradam (also known as the Battle of Enderta) was fought on the northern front of what was known as the Second Italo-Abyssinian War. This battle consisted of attacks and counter-attacks by Italian forces under Marshal of Italy Pietro Badoglio and Ethiopian forces under Ras Mulugeta Yeggazu.', 1936, 2, 10, 1936, 2, 19, 'day', '10 February 1936 – 19 February 1936', 45, 'https://en.wikipedia.org/wiki/Battle_of_Amba_Aradam'),
  ('Q4871088', 'Battle of Genale Doria', 'The Battle of Ganale Doria (also known as the Battle of Genale Dorya or as the Battle of Genale Wenz) took place in 1936 during the Second Italo-Abyssinian War. It was fought on the "southern front".', 1936, 1, 12, 1936, 1, 20, 'day', '12 January 1936 – 20 January 1936', 37, 'https://en.wikipedia.org/wiki/Battle_of_Ganale_Doria'),
  ('Q1410792', 'Second Battle of Amba Alagi', 'The Battle of Amba Alagi was fought in May 1941, during World War II, part of the East African Campaign. After the Italian defeat at Keren in April 1941, Prince Amedeo, Duke of Aosta withdrew his forces to the mountain stronghold at Amba Alagi.', 1941, 5, 4, 1941, 5, 19, 'day', '4 May 1941 – 19 May 1941', 43, 'https://en.wikipedia.org/wiki/Battle_of_Amba_Alagi_(1941)'),
  ('Q1970141', 'Battle of Gondar', 'The Battle of Gondar or Capture of Gondar was the last stand of the Italian forces in Italian East Africa during the Second World War. The battle took place in November 1941, during the East African Campaign.', 1941, 11, 13, 1941, 11, 27, 'day', '13 November 1941 – 27 November 1941', 53, 'https://en.wikipedia.org/wiki/Battle_of_Gondar'),
  ('Q8037478', 'Woyane rebellion', 'The Woyane rebellion (Tigrinya: ቀዳማይ ወያነ, romanized: k’edamay Weyane, lit. ''first Woyane'') was an uprising in the Tigray Province, Ethiopia against the centralization process from the government of Emperor Haile Selassie which took place in May–November 1943. The rebels called themselves the Woyane, a name borrowed from a game played locally between competing groups of young men from different villages, which connoted a spirit of resistance and unity.', 1943, 10, NULL, 1943, 10, NULL, 'month', 'October 1943', 34, 'https://en.wikipedia.org/wiki/Woyane_rebellion'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q29075204', 'Oromo conflict', 'The Oromo conflict or Oromia conflict is a decades-long armed conflict that began in 1973 between the Oromo Liberation Front (OLF) and the Ethiopian government. The Oromo Liberation Front formed to fight the Ethiopian Empire to liberate the Oromo people and establish an independent state of Oromia.', 1973, NULL, NULL, 2018, 8, NULL, 'year', '1973 – August 2018', 37, 'https://en.wikipedia.org/wiki/Oromo_conflict'),
  ('Q257724', 'Ethiopian Civil War', 'The Ethiopian Civil War was a civil war in Ethiopia and present-day Eritrea, fought between the Ethiopian military junta known as the Derg and Ethiopian-Eritrean anti-government rebels from 12 September 1974 to 28 May 1991. The Derg overthrew the Ethiopian Empire and Emperor Haile Selassie in a coup d''état on 12 September 1974, establishing Ethiopia as a communist state under a military junta and provisional government.', 1974, 9, 12, 1991, 6, 4, 'day', '12 September 1974 – 4 June 1991', 71, 'https://en.wikipedia.org/wiki/Ethiopian_Civil_War'),
  ('Q2610662', 'Red Terror', 'The Ethiopian Red Terror, also known as the Qey Shibir (Amharic: ቀይ ሽብር, romanized: ḳäy shəbbər), was a violent political repression campaign of the Derg against other competing Marxist-Leninist groups in Ethiopia and present-day Eritrea from 1976 to 1978. This wave of repression followed Ethiopian People’s Revolutionary Party''s guerrilla assassination campaign, which targeted and killed fifty Derg officials and Derg supporters.', 1976, NULL, NULL, 1977, NULL, NULL, 'year', '1976–1977', 52, 'https://en.wikipedia.org/wiki/Red_Terror_(Ethiopia)'),
  ('Q318250', 'Ogaden War', 'The Ogaden War, also known as the Ethio-Somali War (Somali: Dagaalkii Xoraynta Soomaali Galbeed, Amharic: የኢትዮጵያ ሶማሊያ ጦርነት, romanized: ye’ītiyop’iya somalīya t’orinet), was a military conflict between Somalia and Ethiopia fought from July 1977 to March 1978 over control of the sovereignty of the Ogaden region. Somalia launched an invasion in support of the Western Somali Liberation Front (WSLF) insurgency, triggering a broader inter-state war.', 1977, 7, 12, 1978, 3, 23, 'day', '12 July 1977 – 23 March 1978', 73, 'https://en.wikipedia.org/wiki/Ogaden_War'),
  ('Q1637896', '1983–1985 famine in Ethiopia', 'A widespread famine affected Ethiopia from 1983 to 1985. The worst famine to hit the country in a century, it affected 7.75 million people (out of Ethiopia''s 38–40 million) and left approximately 300,000 to 1.2 million dead.', 1983, NULL, NULL, 1985, NULL, NULL, 'year', '1983–1985', 61, 'https://en.wikipedia.org/wiki/1983%E2%80%931985_famine_in_Ethiopia'),
  ('Q4055748', 'Ethiopian Airlines Flight 604', 'Ethiopian Airlines Flight 604 was a scheduled Addis Ababa–Bahir Dar–Asmara flight operated by a Boeing 737-200 in which the aircraft caught fire during a belly landing in a clearing near Bahir Dar Airport, Bahir Dar, Ethiopia, on 15 September 1988.', 1988, 9, 15, NULL, NULL, NULL, 'day', '15 September 1988', 47, 'https://en.wikipedia.org/wiki/Ethiopian_Airlines_Flight_604'),
  ('Q760007', 'insurgency in Ogaden', 'The Insurgency in Ogaden was an armed conflict that took place from 1992 to 2018. It was waged by nationalist and Islamist Somali insurgent groups seeking self-determination for the region, primarily the Ogaden National Liberation Front (ONLF) and Al-Itihaad Al-Islamiya (AIAI).', 1994, NULL, NULL, 2018, NULL, NULL, 'year', '1994–2018', 47, 'https://en.wikipedia.org/wiki/Insurgency_in_Ogaden'),
  ('Q832273', 'Eritrean–Ethiopian War', 'The Eritrean–Ethiopian War, also known as the Badme War, was a major armed conflict between Ethiopia and Eritrea that took place from May 6, 1998 to June 18, 2000. After Eritrea gained independence from Ethiopia in 1993, relations were initially friendly.', 2000, 6, 18, 2000, 5, 25, 'day', '18 June 2000 – 25 May 2000', 70, 'https://en.wikipedia.org/wiki/Eritrean%E2%80%93Ethiopian_War'),
  ('Q1072042', 'War in Somalia', 'The Ethiopian invasion of Somalia, also known as the Ethiopian occupation of Somalia was an armed conflict lasting from mid-2006 to early 2009. It began when Ethiopian military forces, supported by the United States, invaded Somalia to depose the Islamic Courts Union (ICU) and install the Transitional Federal Government (TFG).', 2006, 12, 20, 2009, 1, 30, 'day', '20 December 2006 – 30 January 2009', 57, 'https://en.wikipedia.org/wiki/War_in_Somalia_(2006%E2%80%932009)'),
  ('Q26237347', '2016 Ethiopian protests', 'The 2014–2016 Oromo protests were a series of protests and resistance in Oromia which first sparked on 25 April 2014. The initial actions were taken in opposition to the Addis Ababa Master Plan, and resumed on 12 November 2015 by university students and farmers in the town of Ginchi, located 80 km southwest of Addis Ababa, encircled by Oromia.', 2016, 8, 5, NULL, NULL, NULL, 'day', '5 August 2016', 52, 'https://en.wikipedia.org/wiki/2014%E2%80%932016_Oromo_protests'),
  ('Q106959326', 'Ethiopian civil conflict (2018–present)', 'The Ethiopian civil conflict is a series of armed conflicts in Ethiopia that have been ongoing since 2018. In November 2019, three of the four constituent parties of the ruling Ethiopian People''s Revolutionary Democratic Front (EPRDF) approved a merger into the Prosperity Party, while the Tigray People''s Liberation Front (TPLF) opposed the move.', 2018, 4, 2, NULL, NULL, NULL, 'day', '2 April 2018', 45, 'https://en.wikipedia.org/wiki/Ethiopian_civil_conflict_(2018%E2%80%93present)'),
  ('Q97176252', 'Hachalu Hundessa riots', 'The Hachalu Hundessa riots were a series of civil unrest that occurred in the Oromia Region of Ethiopia, more specifically in the hot spot of Addis Ababa, Shashamene and Ambo following the killing of the Oromo musician Hachalu Hundessa on 29 June 2020. The riots lead to the deaths of at least 239 people according to initial police reports.', 2020, 6, 29, NULL, NULL, NULL, 'day', '29 June 2020', 43, 'https://en.wikipedia.org/wiki/Hachalu_Hundessa_riots'),
  ('Q101231200', 'Tigray war', 'The Tigray war was an armed conflict that lasted from 3 November 2020 to 3 November 2022. It was a civil war primarily fought in the Tigray Region of Ethiopia between forces allied with the Ethiopian federal government and Eritrea on one side, and the Tigray People''s Liberation Front (TPLF) on the other.', 2020, 11, 3, 2022, 11, 3, 'day', '3 November 2020 – 3 November 2022', 72, 'https://en.wikipedia.org/wiki/Tigray_war'),
  ('Q102133730', 'Battle of Mekelle', 'The Mekelle offensive was a military campaign fought at the start of the Tigray War between the national armed forces of Ethiopia and the Tigray Region. The Ethiopian National Defense Force (ENDF) launched an offensive aimed at seizing the Tigray Peoples Liberation Front (TPLF) controlled regional capital of Mekelle starting on 17 November 2020.', 2020, 11, 17, 2020, 11, 28, 'day', '17 November 2020 – 28 November 2020', 41, 'https://en.wikipedia.org/wiki/Mekelle_offensive'),
  ('Q102301838', 'Mai Kadra massacre', 'The Mai Kadra massacre was a massacre and ethnic cleansing carried out during the Tigray War on 9–10 November 2020 in the town of Mai Kadra in Welkait (a disputed area between the Amhara and Tigray Regions) in northwestern Ethiopia, near the Sudanese border. The victims have been described as civilians, many of whom were day laborers hailing from neighboring Amhara Region.', 2020, 11, 9, 2020, 11, 10, 'day', '9 November 2020 – 10 November 2020', 39, 'https://en.wikipedia.org/wiki/Mai_Kadra_massacre'),
  ('Q104462652', 'Metekel massacre', 'The Metekel massacre was a massacre that took place on the night of 22–23 December 2020, in the Metekel Zone of the Benishangul-Gumuz Region, Ethiopia. As of 23 December 2020, the Ethiopian Human Rights Commission counted 100 deaths.', 2020, 12, 24, 2020, 12, 23, 'day', '24 December 2020 – 23 December 2020', 34, 'https://en.wikipedia.org/wiki/Metekel_massacre'),
  ('Q115124248', 'Ethiopia–Tigray peace agreement', 'The Ethiopia–Tigray peace agreement, also called the Pretoria Agreement or the Cessation of Hostilities Agreement (CoHA), is a peace treaty between the government of Ethiopia and the Tigray People''s Liberation Front (TPLF) that was signed 2 November 2022, wherein both parties agreed to a "permanent cessation of hostilities" to end the Tigray war. The agreement was made effective the next day on 3 November, marking the second anniversary of the war.', 2022, 11, 2, NULL, NULL, NULL, 'day', '2 November 2022', 50, 'https://en.wikipedia.org/wiki/Ethiopia%E2%80%93Tigray_peace_agreement'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods'),
  ('Q121160319', 'War in Amhara', 'The Fano insurgency or Amhara war is an armed conflict and insurgency in the Amhara Region of Ethiopia that began in April 2023 between the Fano militia and the Ethiopian government. The conflict started after the government attempted to dissolve the Amhara Special Forces and other regional forces as part of a plan to reform and centralize the country''s security apparatus, and integrate them into the federal armed forces.', 2023, NULL, NULL, NULL, NULL, NULL, 'year', '2023', 45, 'https://en.wikipedia.org/wiki/Fano_Insurgency'),
  ('Q141544931', '2026 Ethiopian offensive', 'On 23 September 2026, the Ethiopian Peoples'' Forces Coalition for Survival, a coalition of various Ethiopian rebel and insurgent groups, launched a large-scale military offensive against the Ethiopian National Defense Force (ENDF) in Tigray, Afar and Amhara. The Tigray People''s Liberation Front (TPLF) described the offensive as a defensive war against the federal government of Ethiopia.', 2026, 9, 23, NULL, NULL, NULL, 'day', '23 September 2026', 45, 'https://en.wikipedia.org/wiki/2026_Ethiopian_offensive'),
  ('Q141671500', '2026 Eritrean invasion of Ethiopia', 'During the 2026 Ethiopian Offensive, sometime between 28 September and 6 October 2026 (inclusive), the Eritrean Army, which had remained present in Tigray Region in Ethiopia following the Tigray war, were reportedly deployed to several locations in Tigray before pulling back after drone strikes. Ethiopian authorities described the event as an invasion and Eritrean authorities described Ethiopia''s threats to invade Eritrean ports and coastal areas as a declaration of war.', 2026, 10, 6, NULL, NULL, NULL, 'day', '6 October 2026', 30, 'https://en.wikipedia.org/wiki/2026_Eritrean_incursion_into_Ethiopia');
